  <script>
      function toggleLinks() {
          const checkbox = document.getElementById('consent');
          const links = document.querySelectorAll('.role-link');
          const errorMessage = document.getElementById('error-message');
          errorMessage.textContent = ""; // Скрываем ошибку при переключении
          links.forEach(link => {
              link.classList.toggle('disabled', !checkbox.checked);
          });
      }

      function handleLinkClick(event) {
          const checkbox = document.getElementById('consent');
          const errorMessage = document.getElementById('error-message');
          if (!checkbox.checked) {
              event.preventDefault(); // Предотвращаем переход по ссылке
              errorMessage.textContent = "Нужно согласиться с условиями акции.";
          }
      }

      function startCountdown() {
          const endDate = new Date("2025-02-28T23:59:59").getTime();
          const timerElement = document.getElementById('timer');

          function updateCountdown() {
              const now = new Date().getTime();
              const timeRemaining = endDate - now;

              if (timeRemaining <= 0) {
                  timerElement.textContent = "Акция завершена.";
                  clearInterval(timerInterval);
                  return;
              }

              const days = Math.floor(timeRemaining / (1000 * 60 * 60 * 24));
              const hours = Math.floor((timeRemaining % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
              const minutes = Math.floor((timeRemaining % (1000 * 60 * 60)) / (1000 * 60));
              const seconds = Math.floor((timeRemaining % (1000 * 60)) / 1000);

              // timerElement.textContent = `До окончания акции осталось: ${days}д ${hours}ч ${minutes}м ${seconds}с`;
          }

          const timerInterval = setInterval(updateCountdown, 1000);
          updateCountdown();
      }

      // window.onload = startCountdown;

      window.onload = function () {
          // startCountdown();
      };

      // снег 2025
      let snowflakesCount = 200; // Snowflake count, can be overwritten by attrs
      let baseCSS = ``;


      // set global attributes
      if (typeof SNOWFLAKES_COUNT !== 'undefined') {
          snowflakesCount = SNOWFLAKES_COUNT;
      }
      if (typeof BASE_CSS !== 'undefined') {
          baseCSS = BASE_CSS;
      }

      let bodyHeightPx = null;
      let pageHeightVh = null;

      function setHeightVariables() {
          bodyHeightPx = document.body.offsetHeight;
          pageHeightVh = (100 * bodyHeightPx / window.innerHeight);
      }

      // get params set in snow div
      function getSnowAttributes() {
          const snowWrapper = document.getElementById('snow');
          snowflakesCount = Number(
              snowWrapper?.dataset?.count || snowflakesCount
          );
      }

      // Creating snowflakes
      function generateSnow(snowDensity = 200) {
          snowDensity -= 1;
          const snowWrapper = document.getElementById('snow');
          snowWrapper.innerHTML = '';
          for (let i = 0; i < snowDensity; i++) {
              let board = document.createElement('div');
              board.className = "snowflake";
              snowWrapper.appendChild(board);
          }
      }

      function getOrCreateCSSElement() {
          let cssElement = document.getElementById("psjs-css");
          if (cssElement) return cssElement;

          cssElement = document.createElement('style');
          cssElement.id = 'psjs-css';
          document.head.appendChild(cssElement);
          return cssElement;
      }

      // Append style for each snowflake to the head
      function addCSS(rule) {
          const cssElement = getOrCreateCSSElement();
          cssElement.innerHTML = rule; // safe to use innerHTML
          document.head.appendChild(cssElement);
      }

      // Math
      function randomInt(value = 100) {
          return Math.floor(Math.random() * value) + 1;
      }

      function randomIntRange(min, max) {
          min = Math.ceil(min);
          max = Math.floor(max);
          return Math.floor(Math.random() * (max - min + 1)) + min;
      }

      function getRandomArbitrary(min, max) {
          return Math.random() * (max - min) + min;
      }

      // Create style for snowflake
      function generateSnowCSS(snowDensity = 200) {
          let snowflakeName = "snowflake";
          let rule = baseCSS;

          for (let i = 1; i < snowDensity; i++) {
              let randomX = Math.random() * 100; // vw
              let randomOffset = Math.random() * 10 // vw;
              let randomXEnd = randomX + randomOffset;
              let randomXEndYoyo = randomX + (randomOffset / 2);
              let randomYoyoTime = getRandomArbitrary(0.3, 0.8);
              let randomYoyoY = randomYoyoTime * pageHeightVh; // vh
              let randomScale = Math.random();
              let fallDuration = randomIntRange(10, pageHeightVh / 10 * 3); // s
              let fallDelay = randomInt(pageHeightVh / 10 * 3) * -1; // s
              let opacity = Math.random();

              rule += `
      .${snowflakeName}:nth-child(${i}) {
        opacity: ${opacity};
        transform: translate(${randomX}vw, -10px) scale(${randomScale});
        animation: fall-${i} ${fallDuration}s ${fallDelay}s linear infinite;
      }
      @keyframes fall-${i} {
        ${randomYoyoTime * 100}% {
          transform: translate(${randomXEnd}vw, ${randomYoyoY}vh) scale(${randomScale});
        }
        to {
          transform: translate(${randomXEndYoyo}vw, ${pageHeightVh}vh) scale(${randomScale});
        }
      }
    `
          }
          addCSS(rule);
      }

      // Load the rules and execute after the DOM loads
      function createSnow() {
          setHeightVariables();
          getSnowAttributes();
          generateSnowCSS(snowflakesCount);
          generateSnow(snowflakesCount);
      };

      if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
          // код для мобильных устройств
      } else {
          // код для обычных устройств
          document.getElementById('snow').style.display = "block";
          window.addEventListener('resize', createSnow);
          window.addEventListener("DOMContentLoaded", () => {
              createSnow();
          });
      }

  </script>

